+  group('bookmarkMessage() — spec-6-4', () {
+    /// Drives a full send that leaves a user message with [serverId]
+    /// captured (via `message_created`) and its paired AI bubble
+    /// `complete` — the normal precondition every "happy path"-shaped
+    /// bookmark test below starts from.
+    Future<void> sendAndCompleteWithServerId(String serverId) async {
+      await cubit.init();
+      final future = cubit.sendMessage('oi');
+      await Future<void>.delayed(Duration.zero);
+      final controller = fakeRepository.lastSendController!;
+      controller.add(right(ChatMessageCreatedEvent(serverId)));
+      controller.add(right(const ChatDoneEvent()));
+      await controller.close();
+      await future;
+    }
+
+    test(
+      'happy path: idle -> saving -> saved, calling EntriesRepository.'
+      'create(source: chat, chatMessageId: serverId) exactly once',
+      () async {
+        await sendAndCompleteWithServerId('srv-user-1');
+        final userId = (cubit.state as ChatReady).messages[0].id;
+        expect(
+          (cubit.state as ChatReady).messages[0].bookmarkState,
+          const BookmarkState.idle(),
+        );
+
+        await cubit.bookmarkMessage(userId);
+
+        final ready = cubit.state as ChatReady;
+        expect(ready.messages[0].id, userId);
+        expect(ready.messages[0].bookmarkState, const BookmarkState.saved());
+        expect(fakeEntriesRepository.createCalls, [
+          (content: 'oi', source: EntrySource.chat, chatMessageId: 'srv-user-1'),
+        ]);
+        // Only the tapped bubble changed — its paired AI bubble is
+        // untouched (Boundaries: "other bubbles unaffected").
+        expect(ready.messages[1].bookmarkState, const BookmarkState.idle());
+      },
+    );
+
+    test(
+      'the saving state is visible before the EntriesRepository.create() '
+      'call resolves',
+      () async {
+        await sendAndCompleteWithServerId('srv-user-1');
+        final userId = (cubit.state as ChatReady).messages[0].id;
+        final completer = Completer<Either<Failure, Entry>>();
+        fakeEntriesRepository.pendingCompleter = completer;
+
+        final bookmarkFuture = cubit.bookmarkMessage(userId);
+        await Future<void>.delayed(Duration.zero);
+
+        expect(
+          (cubit.state as ChatReady).messages[0].bookmarkState,
+          const BookmarkState.saving(),
+        );
+
+        completer.complete(fakeEntriesRepository.createResult);
+        await bookmarkFuture;
+
+        expect(
+          (cubit.state as ChatReady).messages[0].bookmarkState,
+          const BookmarkState.saved(),
+        );
+      },
+    );
+
+    test(
+      'I/O matrix "Second tap while saving": a re-entrant tap on a '
+      'message already saving is a no-op — exactly one create() call',
+      () async {
+        await sendAndCompleteWithServerId('srv-user-1');
+        final userId = (cubit.state as ChatReady).messages[0].id;
+        final completer = Completer<Either<Failure, Entry>>();
+        fakeEntriesRepository.pendingCompleter = completer;
+
+        final firstBookmark = cubit.bookmarkMessage(userId);
+        await Future<void>.delayed(Duration.zero);
+        expect(fakeEntriesRepository.createCalls, hasLength(1));
+
+        await cubit.bookmarkMessage(userId);
+
+        expect(fakeEntriesRepository.createCalls, hasLength(1));
+
+        completer.complete(fakeEntriesRepository.createResult);
+        await firstBookmark;
+        expect(
+          (cubit.state as ChatReady).messages[0].bookmarkState,
+          const BookmarkState.saved(),
+        );
+      },
+    );
+
+    test(
+      'I/O matrix "Already saved": tapping a saved message again is a '
+      'no-op — no new call, no state change',
+      () async {
+        await sendAndCompleteWithServerId('srv-user-1');
+        final userId = (cubit.state as ChatReady).messages[0].id;
+        await cubit.bookmarkMessage(userId);
+        expect(fakeEntriesRepository.createCalls, hasLength(1));
+
+        await cubit.bookmarkMessage(userId);
+
+        expect(fakeEntriesRepository.createCalls, hasLength(1));
+        expect(
+          (cubit.state as ChatReady).messages[0].bookmarkState,
+          const BookmarkState.saved(),
+        );
+      },
+    );
+
+    test(
+      'I/O matrix "No serverId yet": tapping before message_created '
+      'arrived is a no-op, same guard shape as retryMessage',
+      () async {
+        await cubit.init();
+        final future = cubit.sendMessage('oi');
+        await Future<void>.delayed(Duration.zero);
+        final userId = (cubit.state as ChatReady).messages[0].id;
+        expect((cubit.state as ChatReady).messages[0].serverId, isNull);
+
+        await cubit.bookmarkMessage(userId);
+
+        expect(fakeEntriesRepository.createCalls, isEmpty);
+        expect(
+          (cubit.state as ChatReady).messages[0].bookmarkState,
+          const BookmarkState.idle(),
+        );
+
+        fakeRepository.lastSendController!.add(right(const ChatDoneEvent()));
+        await fakeRepository.lastSendController!.close();
+        await future;
+      },
+    );
+
+    test(
+      'I/O matrix "Save fails": a Left(Failure) flips the bubble to '
+      'error (retryable), the rest of the session stays usable',
+      () async {
+        await sendAndCompleteWithServerId('srv-user-1');
+        final userId = (cubit.state as ChatReady).messages[0].id;
+        fakeEntriesRepository.createResult = left(
+          const Failure.networkTimeout(message: 'timeout'),
+        );
+
+        await cubit.bookmarkMessage(userId);
+
+        final ready = cubit.state as ChatReady;
+        expect(ready.messages[0].bookmarkState, isA<BookmarkError>());
+        expect(
+          (ready.messages[0].bookmarkState as BookmarkError).failure,
+          isA<NetworkTimeout>(),
+        );
+        // The rest of the session is untouched/usable — composer isn't
+        // disabled, the AI bubble is untouched.
+        expect(ready.isSending, isFalse);
+        expect(ready.messages[1].status, ChatMessageStatus.complete);
+      },
+    );
+
+    test(
+      'tapping an error bubble again re-attempts the same save, '
+      'returning to saving then resolving per the new result',
+      () async {
+        await sendAndCompleteWithServerId('srv-user-1');
+        final userId = (cubit.state as ChatReady).messages[0].id;
+        fakeEntriesRepository.createResult = left(
+          const Failure.networkTimeout(message: 'timeout'),
+        );
+        await cubit.bookmarkMessage(userId);
+        expect(
+          (cubit.state as ChatReady).messages[0].bookmarkState,
+          isA<BookmarkError>(),
+        );
+
+        fakeEntriesRepository.createResult = right(
+          const Entry(
+            id: 'entry-2',
+            content: 'oi',
+            source: EntrySource.chat,
+            chatMessageId: 'srv-user-1',
+            occurredAt: '2026-01-01T00:00:00Z',
+            serverRevision: 1,
+            createdAt: '2026-01-01T00:00:00Z',
+            updatedAt: '2026-01-01T00:00:00Z',
+          ),
+        );
+        await cubit.bookmarkMessage(userId);
+
+        expect(
+          (cubit.state as ChatReady).messages[0].bookmarkState,
+          const BookmarkState.saved(),
+        );
+        expect(fakeEntriesRepository.createCalls, hasLength(2));
+      },
+    );
+
+    test(
+      'I/O matrix "Side-effect throws": EntriesRepository.create() '
+      'throwing synchronously is caught by isolatedSideEffect and mapped '
+      'to a BookmarkState.error, never propagating out of the cubit',
+      () async {
+        await sendAndCompleteWithServerId('srv-user-1');
+        final userId = (cubit.state as ChatReady).messages[0].id;
+        fakeEntriesRepository.throwOnCreate = Exception('boom');
+
+        await cubit.bookmarkMessage(userId);
+
+        final ready = cubit.state as ChatReady;
+        expect(ready.messages[0].bookmarkState, isA<BookmarkError>());
+        expect(
+          (ready.messages[0].bookmarkState as BookmarkError).failure,
+          isA<MalformedResponse>(),
+        );
+      },
+    );
+
+    test(
+      'a bookmarkMessage call on an AI (assistant) message is a no-op — '
+      'the affordance only ever exists on user messages',
+      () async {
+        await sendAndCompleteWithServerId('srv-user-1');
