      ),
      child: Center(
        child: _BookmarkIndicator(
          state: message.bookmarkState,
          reduceMotion: reduceMotion,
        ),
      ),
    ),
  );
  return onBookmark == null
      ? bookmarkButton
      : Semantics(
          button: true,
          label: _bookmarkSemanticsLabel(message.bookmarkState),
          excludeSemantics: true,
